MAX_CONTENT_TYPE_HEADER_LENGTH = 1024
_CONTENT_TYPE_GUARD_INSTALLED = '_splunk_content_type_guard'


def _is_log_js_request(cherrypy):
    request = cherrypy.serving.request
    if request.method != 'POST':
        return False

    path = request.path_info.strip('/').split('/')
    return len(path) in (3, 4) and path[-3:] == ['util', 'log', 'js']


def install_content_type_guard(cherrypy):
    request_body_class = cherrypy._cpreqbody.RequestBody
    if getattr(request_body_class, _CONTENT_TYPE_GUARD_INSTALLED, False):
        return

    original_request_body_init = request_body_class.__init__

    def guarded_request_body_init(self, fp, headers, params=None, request_params=None):
        content_type = headers.get('Content-Type')
        if (_is_log_js_request(cherrypy)
                and content_type
                and len(content_type) > MAX_CONTENT_TYPE_HEADER_LENGTH):
            raise cherrypy.HTTPError(400, 'Malformed Content-Type header: value is too long')
        original_request_body_init(self, fp, headers, params, request_params)

    request_body_class.__init__ = guarded_request_body_init
    setattr(request_body_class, _CONTENT_TYPE_GUARD_INSTALLED, True)
